// This axis controls the shape of a turn — how much is said, how deeply the topic
// is examined, and how the turn is organised. It deliberately does not describe a
// speaking register, warmth, or playfulness: that belongs to the character
// expression style, and duplicating it here produced two competing voice
// instructions in the same prompt.
const TONE_DIRECTIVES:Record<ConversationTone,string>={comfortable:"Turn shape: respond at an ordinary conversational length. React to the other participant's latest remark before any report-like enumeration.",warm:"Turn shape: before advancing your own point, explicitly acknowledge the other participant's position and what it gets right. Spend real space on that acknowledgement rather than a single opening clause.",playful:"Turn shape: keep turns short and reactive, following the other participant's lead. Prefer immediate reactions over structured explanation, and do not pad a turn to reach a conclusion.",serious:"Turn shape: examine the topic in depth. Make evidence, assumptions, and counterarguments explicit, and do not leave a disagreement unstated to keep the exchange smooth.",concise:"Turn shape: state the key reaction and the conclusion, then stop. Omit preamble, restatement of the question, and closing summaries."};
const CONVERSATION_LANGUAGE_NAMES:Record<SupportedLocale,string>={ko:"Korean",en:"English",ja:"Japanese"};
function conversationLocale(value:unknown):SupportedLocale{return value==="en"||value==="ja"?value:"ko";}
export function conversationLanguageDirective(value:unknown){const fallback=CONVERSATION_LANGUAGE_NAMES[conversationLocale(value)];return`Response language: Reply in the language used by the latest user-authored message. If that message is too short, language-neutral, or mainly a quotation, continue the established conversation language. At the start of an ambiguous conversation, default to the session interface language: ${fallback}. Preserve the selected character style when changing languages; examples written in another language are style references and must be translated naturally, not copied verbatim.`;}
export function conversationStyle(tone:unknown){const selected=(typeof tone==="string"&&tone in TONE_DIRECTIVES?tone:"comfortable") as ConversationTone;return{tone:selected,directive:["Respond in-character as a feminine character in the active conversation language.","Emotional expression, including strong affection, is allowed when it fits the selected conversation tone and context.","Do not impose gender stereotypes.",TONE_DIRECTIVES[selected],"This setting governs the shape of a turn only. Where it appears to conflict with the character expression style, the expression style wins: never soften, warm, or neutralise the selected character voice to satisfy it."].join("\n")};}
export function debateDirective(content:string){const match=content.match(DEBATE_DIRECTIVE);return{signal:(match?.[1]?.toLowerCase()??"continue") as "continue"|"conclude"|"agree",agreementChecksum:match?.[2]?.toLowerCase()??null,content:content.replace(DEBATE_DIRECTIVE,"").trim()};}
export function conversationDirective(content:string){const match=content.match(CONVERSATION_DIRECTIVE);return{signal:(match?.[1]?.toLowerCase()??"yield") as "continue"|"yield"|"end",content:content.replace(CONVERSATION_DIRECTIVE,"").trim()};}
